var findBuildings = function(heights) {
    const res = [];
    let maxH = 0;
    for (let i = heights.length - 1; i >= 0; --i) {
        if (heights[i] > maxH) {
            res.push(i);
            maxH = heights[i];
        }
    }
    return res.reverse();
};
